const fs=require('node:fs'),vm=require('node:vm'),assert=require('node:assert/strict'),path=require('node:path');
const root=path.resolve(__dirname,'..'),E=require('../engine.js'),C=require('../coach.js');
let checks=0;function test(name,fn){fn();checks++;console.log('PASS '+name);}
const now=1_000_000;
test('Failure schedules a ten-minute retry',()=>{const p=E.schedule(null,0,now);assert.equal(p.due,now+600000);assert.equal(p.correct,0);assert.equal(p.lastCorrect,false);});
test('Successful recalls grow the interval',()=>{let p=E.schedule(null,2,now);assert.equal(p.interval,1);p=E.schedule(p,2,now);assert.equal(p.interval,3);p=E.schedule(p,2,now);assert.ok(p.interval>3);assert.equal(p.correct,3);});
test('Hesitant recall returns tomorrow',()=>assert.equal(E.schedule(null,1,now).interval,1));
test('Accuracy is based on attempts, without invented initial values',()=>{assert.equal(E.accuracy({}),null);assert.equal(E.accuracy({x:{attempts:4,correct:3}}),75);});
