const arithmetic={a001:(.02*16+.01*4)/.03,a002:100*.04*(1+.25*(7-3))**(-1/.25),a005:8/3,a006:.72/.48,a007:50*(1+Math.exp(-.08)),a008:.4+12*(-.015),a009:100*(.10-.04)/(1-.04),a010:(.20+.06-.20**2/2)/.20,a011:.4*(.5*3*.01+.5*15*.05),a012:13-5-6*.9,a013:100*(.07-.04)/(.10-.04),a016:100*.015/(1-.25),a017:100*.04*.3,a018:5*.8,a023:18-120*.12,a024:Math.max(70,120*.725)*.10,a025:100*72/(120-Math.min(100,.75*120)),a026:100*(80*.95+40*.5)/(100*.85),a027:200*.95-180*.9,a028:50+(80-30)*.8,a029:-(4*150-2*135)*.01,a030:-Math.min(-8,-8-7,-8-7+12,-8-7+12+6),a031:.3/.25,a032:2+(11-2)*10/15,a033:.2*(-.015*.8+.01*.2),a034:60*.09+40*.04,a035:(-1-.5*3)/.5,a036:8/(1-.8),a038:.6*5+.4*12};
test('All 29 reserved numerical cases are independently recomputed',()=>{const qs=JSON.parse(run('JSON.stringify(ASSESSMENT_QUESTIONS.filter(q=>q.value!==null))'));assert.equal(qs.length,29);for(const q of qs){assert.ok(q.id in arithmetic);assert.ok(Math.abs(q.value-arithmetic[q.id])<1e-5,q.id);if(['a005','a036'].includes(q.id)){assert.equal(q.answer,1);continue;}const numbers=[...q.choices[q.answer].replace(/−/g,'-').matchAll(/[-+]?\d+(?:\.\d+)?/g)].map(x=>({n:+x[0],tol:.5*10**(-(x[0].split('.')[1]?.length||0))+.000001}));assert.ok(numbers.some(x=>Math.abs(x.n-arithmetic[q.id])<=x.tol),q.id+' chosen '+q.choices[q.answer]);}});
test('Readiness is zero and provisional with no evidence, without invented back-history',()=>{const s=run('defaults()'),r=R.score(s,run('ALL_QUESTIONS'),run('SKILLS'));assert.equal(r.score,0);assert.equal(r.n,0);assert.ok(r.provisional);assert.equal(s.readinessHistory.length,0);});
const clockNow=Date.now(),sampleQuestions=run('SKILLS').flatMap(s=>[0,1].map(i=>({id:s.id+i,topic:s.topic,skill:s.id})));
const scoreState=()=>({quiz:{},cards:{},exposed:{},evidence:{},retention:{},readinessHistory:[]});
test('Readiness formula independently reaches 100 with complete fresh, retained and timed evidence',()=>{const s=scoreState();sampleQuestions.forEach((q,i)=>{s.evidence[q.id]={at:clockNow,correct:true,timed:true};if(i<24)s.retention[q.id]={at:clockNow,correct:true};});const r=R.score(s,sampleQuestions,run('SKILLS'),clockNow);assert.equal(r.score,100);for(const [key,value]of Object.entries({performance:60,breadth:20,retention:10,pace:10}))assert.ok(Math.abs(r.components[key]-value)<1e-8);assert.equal(r.provisional,false);});
test('Incorrect fresh answers alone cannot earn readiness points',()=>{const s=scoreState();sampleQuestions.forEach(q=>s.evidence[q.id]={at:clockNow,correct:false,timed:true});assert.equal(R.score(s,sampleQuestions,run('SKILLS'),clockNow).score,0);});
test('An unassessed domain remains visible and contributes no inferred performance',()=>{const s=scoreState();s.evidence[sampleQuestions[0].id]={at:clockNow,correct:true};const r=R.score(s,sampleQuestions,run('SKILLS'),clockNow);assert.equal(r.components.performance,12);assert.equal(r.domains.filter(d=>d.accuracy===null).length,5);assert.ok(r.provisional);});
test('Immediate retry accuracy and card ratings cannot inflate the fresh score',()=>{const s=scoreState(),q=sampleQuestions[0];s.evidence[q.id]={at:clockNow,correct:false};s.quiz[q.id]={attempts:100,correct:99};s.cards[q.id]={attempts:100,correct:100};assert.equal(R.score(s,sampleQuestions,run('SKILLS'),clockNow).score,0);});
test('Evidence ages out after 42 days and the score can decrease',()=>{const s=scoreState();s.evidence[sampleQuestions[0].id]={at:clockNow,correct:true};const before=R.score(s,sampleQuestions,run('SKILLS'),clockNow);const after=R.score(s,sampleQuestions,run('SKILLS'),clockNow+43*86400000);assert.ok(before.score>after.score);assert.equal(after.n,0);assert.equal(after.old,1);});
test('Trend snapshots deduplicate identical same-day observations and preserve genuine later dates',()=>{const s=scoreState();R.snapshot(s,sampleQuestions,run('SKILLS'),clockNow);R.snapshot(s,sampleQuestions,run('SKILLS'),clockNow+100);assert.equal(s.readinessHistory.length,1);s.evidence[sampleQuestions[0].id]={at:clockNow+200,correct:true};R.snapshot(s,sampleQuestions,run('SKILLS'),clockNow+300,'practice');R.snapshot(s,sampleQuestions,run('SKILLS'),clockNow+86400000);assert.equal(s.readinessHistory.length,3);assert.equal(s.readinessHistory[0].score,0);assert.equal(s.readinessHistory[1].reason,'practice');});
function click(dataset){return run(`Upgrade.handleClick({target:{closest(){return {dataset:${JSON.stringify(dataset)},disabled:false}}}})`);}
function prepareAssessment(kind='checkpoint'){run(`state=defaults();Upgrade.startAssessment('${kind}')`);element('#start-assessment').onclick();}
test('Fresh checkpoints have exact weights, unique items, protected corrections and editable answers',()=>{prepareAssessment();assert.equal(run('state.session.items.length'),20);assert.equal(run('state.session.targetMs'),3600000);assert.equal(run('new Set(state.session.items.map(i=>i.id)).size'),20);for(const[t,n]of Object.entries({market:4,credit:4,operational:4,liquidity:3,investment:3,current:2}))assert.equal(run(`state.session.items.filter(i=>qFor(i.id).topic==='${t}').length`),n);assert.equal(run('state.session.items.every(i=>i.fresh)'),true);click({examChoice:'0'});click({examChoice:'2'});assert.equal(run('state.session.items[0].selected'),2);assert.equal(run('Object.keys(state.quiz).length'),0);const html=element('#app').innerHTML;assert.ok(!html.includes('Analyser les quatre choix'));assert.ok(!html.includes(run('rich(qFor(state.session.items[0].id).explanation)')));click({examFlag:'yes'});assert.equal(run('state.session.items[0].flagged'),true);click({examGo:'3'});assert.equal(run('state.session.index'),3);assert.ok(click({page:'formula'}));assert.equal(run('page'),'study');});
test('Active exams survive JSON recovery with deadline, choices and flags intact',()=>{run('var recoveredExam=validate(JSON.parse(JSON.stringify(state)))');assert.equal(run('recoveredExam.session.deadline'),run('state.session.deadline'));assert.equal(run('recoveredExam.session.items[0].flagged'),true);assert.equal(run('recoveredExam.session.items[0].selected'),2);assert.equal(run('recoveredExam.session.items[0].fresh'),true);assert.ok(run('recoveredExam.session.items.every(i=>!i.answered)'));});
test('Final submission scores once, counts blanks as wrong, records fresh evidence and unlocks review',()=>{const selected=run('state.session.items[0].id');run('Upgrade.submitExam();Upgrade.submitExam()');assert.equal(run('state.session'),null);assert.equal(run('state.assessments.length'),1);assert.equal(run('Object.keys(state.quiz).length'),20);assert.equal(run('state.log.length'),20);assert.equal(run('Object.keys(state.evidence).length'),20);assert.equal(run('state.assessments[0].items.filter(i=>i.selected===null).length'),19);assert.equal(run('state.quiz["'+selected+'"].attempts'),1);click({assessmentReview:'0'});assert.ok(element('#modalcontent').innerHTML.includes('Réponse :'));assert.equal(run('state.readinessHistory.at(-1).reason'),'assessment');});
test('Second checkpoint excludes the first 20 items; exhaustion is explicit',()=>{run('var firstIds=state.assessments[0].items.map(x=>x.id);Upgrade.startAssessment("checkpoint")');element('#start-assessment').onclick();assert.ok(run('state.session.items.every(i=>!firstIds.includes(i.id))'));run('Upgrade.submitExam()');assert.equal(run('Upgrade.chooseAssessment("checkpoint").length'),0);});
test('A full mock has 80 questions, four hours and exact exam domain weights',()=>{prepareAssessment('mock');assert.equal(run('state.session.items.length'),80);assert.equal(run('state.session.deadline-state.session.started'),14400000);assert.ok(run('validate(JSON.parse(JSON.stringify(state))).session'));for(const [t,n]of Object.entries(run('EXAM_BLUEPRINT')))assert.equal(run(`state.session.items.filter(i=>qFor(i.id).topic==='${t}').length`),n);});
test('A repeated mock labels reused items and cannot create fresh evidence for them',()=>{run('Upgrade.submitExam();QUESTIONS.filter(q=>q.tier).forEach(q=>state.exposed[q.id]=Date.now());Upgrade.startAssessment("mock")');element('#start-assessment').onclick();assert.ok(run('state.session.items.some(i=>!i.fresh)'));const prior=run('Object.keys(state.evidence).length');run('Upgrade.submitExam()');assert.equal(run('Object.keys(state.evidence).length'),prior);});
test('Assessment timing uses the persisted deadline and auto-submits overdue recovery without grading twice',()=>{prepareAssessment('short');run('state.session.started=Date.now()-1800001;state.session.deadline=Date.now()-1;state.session.items[0].selected=qFor(state.session.items[0].id).answer;var expiredCopy=JSON.stringify(state);state=validate(JSON.parse(expiredCopy));render();render()');assert.equal(run('state.session'),null);assert.equal(run('state.assessments.length'),1);assert.equal(run('state.assessments[0].items.filter(i=>i.correct).length'),1);assert.equal(run('state.history[0].elapsed'),1800000);});
test('Viewed questions are not fresh even without a submitted answer',()=>{run('state=defaults();launchSelection("quiz",[HARD[0]]);state.session=null;launchSelection("quiz",[HARD[0]]);state.session.items[0].selected=HARD[0].answer;submit()');assert.equal(run('state.session.items[0].fresh'),false);assert.equal(run('state.evidence.h001'),undefined);});
test('Opening a card or correction prevents the corresponding question from becoming fresh',()=>{run('state=defaults();showDetail("h001");launchSelection("quiz",[HARD[0]]);state.session.items[0].selected=HARD[0].answer;submit()');assert.equal(run('state.evidence.h001'),undefined);run('state=defaults();launchSelection("cards",[HARD[0]]);state.session=null;launchSelection("quiz",[HARD[0]])');assert.equal(run('state.session.items[0].fresh'),false);});
test('Looking up a correction while a quiz is paused cancels its fresh evidence flag',()=>{run('state=defaults();launchSelection("quiz",[HARD[0]]);navigate("home");showDetail("h001");closeModal();navigate("study");state.session.items[0].selected=HARD[0].answer;submit()');assert.equal(run('state.session.items[0].fresh'),false);assert.equal(run('state.evidence.h001'),undefined);});
test('Reserved answers remain hidden if a detail link is requested before assessment',()=>{run('state=defaults();showDetail("a001")');assert.ok(element('#toast').textContent.includes('réservée'));});
test('Correction lessons persist teach-back and require self-check before a different transfer problem',()=>{run('state=defaults();launchSelection("quiz",[HARD[0]]);state.session.items[0].selected=(HARD[0].answer+1)%4;submit();Upgrade.lesson("h001")');assert.ok(element('#modalcontent').innerHTML.includes('Repérer le mécanisme'));click({lessonNext:'h001'});assert.equal(run('state.lessons.h001.step'),1);click({lessonNext:'h001'});assert.equal(run('state.lessons.h001.step'),1);handlers.input({target:{dataset:{lessonText:'h001'},value:'Use the full tail numerator, then divide by one minus shape.'}});click({lessonNext:'h001'});assert.equal(run('state.lessons.h001.step'),2);click({lessonTransfer:'h001'});assert.equal(run('state.lessons.h001.transfer'),null);click({lessonCheck:'h001'});click({lessonTransfer:'h001'});assert.notEqual(run('state.lessons.h001.transfer'),'h001');assert.ok(element('#modalcontent').innerHTML.includes('TEST DE TRANSFERT'));assert.ok(!element('#modalcontent').innerHTML.includes('Analyser les quatre choix'));run('Upgrade.answerTransfer("h001",qFor(state.lessons.h001.transfer).answer,false)');assert.equal(run('state.lessons.h001.step'),3);assert.equal(run('state.lessons.h001.transferCorrect'),true);const before=run('state.log.length');run('Upgrade.answerTransfer("h001",0,false)');assert.equal(run('state.log.length'),before);});
test('A delayed lesson cannot run early and retains rule, transfer and result through export validation',()=>{const count=run('state.log.length');run('Upgrade.transfer("h001",true);var repairedCopy=validate(JSON.parse(JSON.stringify(state)))');assert.equal(run('state.log.length'),count);assert.equal(run('repairedCopy.lessons.h001.step'),3);assert.equal(run('repairedCopy.lessons.h001.transferCorrect'),true);assert.equal(run('repairedCopy.lessons.h001.text'),run('state.lessons.h001.text'));assert.equal(run('Object.keys(repairedCopy.evidence).length'),run('Object.keys(state.evidence).length'));assert.equal(run('repairedCopy.readinessHistory.length'),run('state.readinessHistory.length'));});
test('Objective retention requires a full day since the last attempt and last exposure',()=>{run('state=defaults();var oldAt=Date.now()-2*Readiness.DAY;state.quiz.h001={...Engine.schedule(null,2,oldAt),...Coach.annotate(null,true,{now:oldAt,day:"2026-10-15"})};state.exposed.h001=Date.now()-1000;launchSelection("quiz",[HARD[0]]);state.session.items[0].selected=HARD[0].answer;submit()');assert.equal(run('state.retention.h001'),undefined);run('state.session=null;state.quiz.h001.last=Date.now()-2*Readiness.DAY;state.exposed.h001=Date.now()-2*Readiness.DAY;launchSelection("quiz",[HARD[0]]);state.session.items[0].selected=HARD[0].answer;submit()');assert.equal(run('state.retention.h001.correct'),true);});
test('Old backups preserve attempts, notes and exam date without manufacturing readiness history',()=>{run('var v4=validate({version:1,exam:"2026-11-24",quiz:{q001:{attempts:7,correct:5,due:1000}},notes:{q001:"retained"},cards:{},history:[{date:1,total:5,correct:3}]})');assert.equal(run('v4.quiz.q001.attempts'),7);assert.equal(run('v4.notes.q001'),'retained');assert.equal(run('v4.exam'),'2026-11-24');assert.equal(run('v4.readinessHistory.length'),0);assert.equal(run('Object.keys(v4.evidence).length'),0);assert.equal(run('v4.history.length'),1);});
test('All readiness and lesson text escapes imported user content',()=>{run('state=defaults();state.lessons.h001={step:2,text:"<script>bad()</script>",checked:false};Upgrade.lesson("h001")');assert.ok(element('#modalcontent').innerHTML.includes('&lt;script&gt;'));assert.ok(!element('#modalcontent').innerHTML.includes('<script>'));});
test('Foundational questions do not count as exam-readiness evidence',()=>{run('state=defaults();launchSelection("quiz",[QUESTIONS[0]]);state.session.items[0].selected=QUESTIONS[0].answer;submit()');assert.equal(run('Object.keys(state.evidence).length'),0);assert.equal(run('state.quiz.q001.correct'),1);});
test('Backgrounding pauses practice time but never stops an assessment deadline',()=>{prepareAssessment('short');const remaining=run('Upgrade.remaining()'),NativeDate=context.Date;try{const later=Date.now()+120000;context.Date=class extends Date{static now(){return later}};run('pauseClock()');assert.ok(run('Upgrade.remaining()')<remaining-119000);assert.equal(run('state.session.targetMs'),1800000);}finally{context.Date=NativeDate;run('state=defaults()');}});
test('A due lesson produces objective delayed-recall evidence and cannot score twice',()=>{run('state=defaults();var ago=Date.now()-2*Readiness.DAY;state.lessons.h001={step:3,text:"A saved rule",checked:true,transfer:"e004",transferCorrect:true,at:ago,delayedCorrect:null};state.quiz.e004={...Engine.schedule(null,2,ago),...Coach.annotate(null,true,{now:ago,day:"2026-10-15"})};state.exposed.e004=ago;state.evidence.e004={at:ago,correct:true,timed:false};Upgrade.transfer("h001",true);Upgrade.answerTransfer("h001",qFor("e004").answer,true)');assert.equal(run('state.lessons.h001.delayedCorrect'),true);assert.equal(run('state.retention.e004.correct'),true);const count=run('state.log.length');run('Upgrade.answerTransfer("h001",qFor("e004").answer,true)');assert.equal(run('state.log.length'),count);});

const P=require('../campaign.js');
function mock(paper,score,date='2026-10-18',extra={}){return {id:paper+date,paper,date,score,total:80,minutes:240,conditions:true,firstAttempt:true,weakReadings:[],...extra};}
test('Campaign calendar uses Paris dates and stops on the chosen exam date',()=>{const c=P.defaults();c.start='2026-10-18';const cal=P.calendar(c,'2026-11-24','2026-10-18');assert.equal(cal.length,38);assert.equal(cal[0].left,37);assert.equal(cal.at(-1).phase,'exam');assert.equal(cal.at(-1).minutes,0);assert.equal(P.dateKey(Date.parse('2026-10-18T22:30:00Z')),'2026-10-19');});
test('The three full mocks are scheduled before the final light days, with next-day review',()=>{const c=P.defaults();c.start='2026-10-18';const cal=P.calendar(c,'2026-11-24','2026-10-18');const full=cal.filter(x=>['mock','official1','official2'].includes(x.event));assert.deepEqual(full.map(x=>x.date),['2026-11-01','2026-11-08','2026-11-15']);assert.ok(full.every(x=>x.minutes===240));assert.ok(cal.find(x=>x.date==='2026-11-09').reviewDay);assert.ok(cal.filter(x=>['2026-11-22','2026-11-23'].includes(x.date)).every(x=>x.phase==='taper'&&x.minutes<=30));});
test('Study settings change ordinary budgets without shortening a full assessment',()=>{const c=P.defaults();c.start='2026-10-18';c.weekdayMinutes=60;c.weekendMinutes=120;const cal=P.calendar(c,'2026-11-24','2026-10-18');assert.equal(cal.find(x=>x.date==='2026-10-19').minutes,60);assert.equal(cal.find(x=>x.date==='2026-10-18').minutes,120);assert.equal(cal.find(x=>x.date==='2026-11-08').minutes,240);});
test('Official mock evidence never treats a repeat, assisted attempt, overtime or a provider mock as an official fresh result',()=>{const c=P.defaults();c.mockResults=[mock('official1',60),mock('official1',75,'2026-10-19',{firstAttempt:false}),mock('official2',60,'2026-10-18',{conditions:false}),mock('provider',80)];let r=P.officialSummary(c,'2026-10-20');assert.equal(r.count,1);assert.equal(r.meetTarget,1);c.mockResults.push(mock('official2',70,'2026-10-19',{minutes:260}));assert.equal(P.officialSummary(c,'2026-10-20').count,1);});
test('Official validation targets are configurable study goals with no inferred pass probability',()=>{const c=P.defaults();c.targetAccuracy=75;c.mockResults=[mock('official1',56),mock('official2',64)];let r=P.officialSummary(c,'2026-10-18');assert.equal(r.count,2);assert.equal(r.meetTarget,1);assert.equal(r.average,.75);assert.equal(r.passProbability,undefined);});
test('Future dated mock results do not become current readiness evidence',()=>{const c=P.defaults();c.mockResults=[mock('official1',80,'2026-11-01')];assert.equal(P.officialSummary(c,'2026-10-18').count,0);});
test('Planner chooses due errors and new objectives while excluding checkpoints and early retries',()=>{const now=Date.now(),state={quiz:{wrong:{lastCorrect:false,due:now-1,wrongConfidence:'high'},wait:{lastCorrect:false,due:now+100000}},cards:{},exposed:{},evidence:{}};const qs=[{id:'wrong',tier:'exam',topic:'credit',objective:'CR-9.5'},{id:'wait',tier:'exam',topic:'market',objective:'MR-1.1'},{id:'new',tier:'coverage',topic:'investment',objective:'IM-1.1'},{id:'reserved',tier:'checkpoint',topic:'current',objective:'CI-1.1'}];const chosen=P.select(state,qs,{count:4,now});assert.ok(chosen.some(q=>q.id==='wrong'));assert.ok(chosen.some(q=>q.id==='new'));assert.ok(chosen.every(q=>!['wait','reserved'].includes(q.id)));assert.equal(new Set(chosen.map(q=>q.id)).size,chosen.length);});
test('Repeated planner calls are stable for the same day and evidence',()=>{run('state=defaults()');const a=run('Campaign.select(state,QUESTIONS,{count:15,date:"2026-10-18"}).map(q=>q.id).join()'),b=run('Campaign.select(state,QUESTIONS,{count:15,date:"2026-10-18"}).map(q=>q.id).join()');assert.equal(a,b);});
test('Reading declarations do not displace observed priorities or inflate the score',()=>{run('state=defaults();var planA=ExamPrep.todayPlan();var firstReading=planA.readings[0].id;state.campaign.readings[firstReading]={status:"read",at:Date.now(),notes:"my rule"};var planB=ExamPrep.todayPlan()');assert.equal(run('planA.readings.map(r=>r.id).join()'),run('planB.readings.map(r=>r.id).join()'));assert.equal(run('Object.keys(state.evidence).length'),0);assert.equal(run('Readiness.score(state,ALL_QUESTIONS,SKILLS).score'),0);});
test('Freshly imported v5 progress gets a new plan without losing score history',()=>{run('var prior={...defaults(),quiz:{q001:{attempts:3,correct:2,due:1}},readinessHistory:[{at:Date.now(),score:40,n:20,timed:0,delayed:0,version:1,reason:"practice"}]};delete prior.campaign;var migrated=validate(prior)');assert.equal(run('migrated.quiz.q001.attempts'),3);assert.equal(run('migrated.readinessHistory[0].score'),40);assert.equal(run('migrated.campaign.weekdayMinutes'),90);});
test('Reading notes, official results and study settings survive backup validation',()=>{run('state=defaults();state.campaign.weekdayMinutes=120;state.campaign.readings["CR-9"]={status:"read",notes:"<rule>",at:Date.now()};state.campaign.mockResults=[{id:"m1",paper:"official1",date:Campaign.dateKey(),score:58,total:80,minutes:235,firstAttempt:true,conditions:true,weakReadings:["CR-9"],notes:"Check conditioning"}];var restoredPlan=validate(JSON.parse(JSON.stringify(state)))');assert.equal(run('restoredPlan.campaign.weekdayMinutes'),120);assert.equal(run('restoredPlan.campaign.readings["CR-9"].notes'),'<rule>');assert.equal(run('restoredPlan.campaign.mockResults[0].score'),58);assert.equal(run('restoredPlan.campaign.mockResults[0].weakReadings[0]'),'CR-9');});
test('Invalid settings, unknown reading IDs and impossible mock scores are sanitized on import',()=>{const c=P.clean({weekdayMinutes:999,weekendMinutes:-5,readings:{FAKE:{status:'read'}},mockResults:[mock('official1',81),mock('official2',-1)]},run('SYLLABUS'));assert.equal(c.weekdayMinutes,240);assert.equal(c.weekendMinutes,30);assert.equal(Object.keys(c.readings).length,0);assert.equal(c.mockResults.length,0);});
test('Plan screen separates declared results from observed evidence and escapes imported notes',()=>{run('state=defaults();state.campaign.mockResults=[{id:"x",paper:"provider",date:Campaign.dateKey(),score:60,total:80,minutes:240,conditions:true,firstAttempt:true,sourceName:"<script>",notes:"<img bad>",weakReadings:[]}];navigate("plan")');const html=element('#app').innerHTML;assert.ok(html.includes('résultats saisis ne modifient pas'));assert.ok(html.includes('&lt;script&gt;'));assert.ok(!html.includes('<script>'));assert.ok(html.includes('sans question précisément reliée'));});
test('Daily sessions start with applied questions and persist a campaign marker',()=>{run('state=defaults();ExamPrep.startDaily(5)');assert.equal(run('state.session.items.length'),5);assert.equal(run('state.session.campaign'),true);assert.ok(run('state.session.items.every(i=>qFor(i.id).tier&&qFor(i.id).tier!=="checkpoint")'));assert.equal(run('validate(JSON.parse(JSON.stringify(state))).session.campaign'),true);});
test('The timed 20-question mixed block respects 4/4/4/3/3/2 and hides corrections',()=>{prepareAssessment('block20');assert.equal(run('state.session.items.length'),20);assert.equal(run('state.session.targetMs'),3600000);assert.equal(run('state.session.label'),'Bloc chronométré 20 Q');assert.ok(!element('#app').innerHTML.includes('Analyser les quatre choix'));});
test('All new plan actions are blocked during an active closed-book assessment',()=>{const blocked=run('ExamPrep.handleClick({target:{closest(){return {dataset:{prepReading:"MR-1"},disabled:false}}}})');assert.ok(blocked);assert.ok(element('#toast').textContent.includes('Remets ta copie'));assert.equal(run('page'),'study');});
test('Official result entry persists separately from the practice score and deduplicates first-attempt claims',()=>{run('state=defaults();state.session=null;ExamPrep.mockModal("official1")');const fill=()=>{for(const [id,value]of Object.entries({'#mock-paper':'official1','#mock-date':run('Campaign.dateKey()'),'#mock-score':'56','#mock-minutes':'240','#mock-provider':'','#mock-readings':'CR-9, IM-17','#mock-notes':'Separate cumulative and conditional PD.'}))element(id).value=value;element('#mock-first').checked=true;element('#mock-conditions').checked=true;};fill();element('#save-mock').onclick();assert.equal(run('state.campaign.mockResults.length'),1);assert.equal(run('Object.keys(state.evidence).length'),0);run('ExamPrep.mockModal("official1")');fill();element('#save-mock').onclick();assert.equal(run('state.campaign.mockResults[1].firstAttempt'),false);assert.equal(run('Campaign.officialSummary(state.campaign).count'),1);});
test('A complete high practice score still exposes missing official-mock validation',()=>{run('state=defaults()');const html=run('ExamPrep.safetyPanel()');assert.ok(html.includes('0/2'));assert.ok(html.includes('garantie de réussite'));assert.ok(html.includes('objectifs restent'));});
test('Programme filter exposes the new cases and keeps reserved questions separate',()=>{run('state=defaults();tier="coverage"');assert.equal(run('tierQuestions("quiz").length'),372);assert.equal(run('tierQuestions("cards").length'),372);assert.equal(run('CARDS.length'),584+run('DEEP_QUESTIONS.length+DEEP_REASONING_CARDS.length'));assert.ok(run('tierQuestions("quiz").every(q=>q.id.startsWith("b"))'));});
test('New coverage IDs and metadata survive session and progress recovery',()=>{run('state=defaults();launchSelection("quiz",[COVERAGE_BANK[0]]);state.session.items[0].selected=COVERAGE_BANK[0].answer;submit();var newRecovered=validate(JSON.parse(JSON.stringify(state)))');assert.equal(run('newRecovered.quiz.b001.correct'),1);assert.equal(run('newRecovered.session.items[0].id'),'b001');assert.ok(run('newRecovered.evidence.b001.correct'));});
test('A recently declared reading does not suppress a weakness reported in a mock',()=>{run('state=defaults();state.campaign.readings["CR-9"]={status:"read",at:Date.now()};state.campaign.mockResults=[{date:Campaign.dateKey(),paper:"official1",weakReadings:["CR-9"]}]');const q=run('Campaign.readingQueue(state,ALL_QUESTIONS,SYLLABUS,{count:1})[0].id');assert.equal(q,'CR-9');});

test('The roadmap lists all107readings and explains limited evidence without invented scores',()=>{run('state=defaults();navigate("roadmap")');const html=element('#app').innerHTML;assert.ok(html.includes('107'));assert.ok(html.includes('À diagnostiquer'));assert.ok(!html.includes('undefined'));for(const id of run('SYLLABUS.map(r=>r.id)'))assert.ok(html.includes('data-road-chapter="'+id+'"'),id);assert.equal(run('state.roadmap.history.length'),1);assert.equal(run('state.roadmap.history[0].assessed'),0);});
test('A chapter opens its dimensions, traps, worked problem and formula references safely',()=>{run('RoadmapUI.chapter("CR-9")');const html=element('#modalcontent').innerHTML;for(const label of ['Comprendre','Appliquer','Raisonner','Retrouver après délai','Les pièges','Un problème travaillé'])assert.ok(html.includes(label));assert.ok(html.includes('data-road-diagnostic="CR-9"'));assert.ok(html.includes('PDF p.'));assert.ok(html.includes('katex'));});
test('Declared chapter perception and notes survive export while remaining separate from observed scores',()=>{run('state=defaults();RoadmapUI.chapter("CR-9")');element('#road-self-understanding').value='1';element('#road-self-application').value='3';element('#road-self-critical').value='2';element('#road-notes').value='<img onerror=bad> My rule';run('RoadmapUI.handleClick({target:{closest(){return {dataset:{roadSave:"CR-9"}}}}});var roadRestored=validate(JSON.parse(JSON.stringify(state)))');assert.equal(run('roadRestored.roadmap.self["CR-9"].understanding'),1);assert.equal(run('roadRestored.roadmap.self["CR-9"].notes'),'<img onerror=bad> My rule');assert.ok(!element('#modalcontent').innerHTML.includes('<img'));assert.equal(run('Readiness.score(state,ALL_QUESTIONS,SKILLS).score'),0);assert.equal(run('RoadmapUI.data().find(r=>r.id==="CR-9").score'),null);});
test('A chapter diagnostic preserves fresh flags and excludes reserved questions',()=>{run('state=defaults();RoadmapUI.launch("CR-9","diagnostic",6)');assert.equal(run('state.session.roadmap'),true);assert.ok(run('state.session.items.every(i=>i.fresh&&qFor(i.id).objective.split(".")[0]==="CR-9"&&qFor(i.id).tier!=="checkpoint")'));const id=run('state.session.items[0].id');run('state.session.items[0].selected=qFor(state.session.items[0].id).answer;submit()');assert.ok(run(`state.evidence[${JSON.stringify(id)}].correct`));assert.ok(run('state.roadmap.history.some(h=>h.assessed>0)'));});
test('Critical-thinking training uses critical cases rather than filling from another dimension',()=>{run('state=defaults();RoadmapUI.launch("IM-1","critical",5)');assert.ok(run('state.session.items.length>0'));assert.ok(run('state.session.items.every(i=>qFor(i.id).dimension==="critical")'));});
test('All roadmap revision actions are blocked during an active assessment',()=>{prepareAssessment('short');for(const key of ['roadChapter','roadDiagnostic','roadPractice','roadCards','roadMixed'])assert.ok(run(`RoadmapUI.handleClick({target:{closest(){return {dataset:{${key}:"MR-1"}}}}})`));assert.equal(run('page'),'study');assert.ok(element('#toast').textContent.includes('Remets ta copie'));});
test('A new chapter reasoning card is recoverable without creating quiz evidence',()=>{run('state=defaults();launchSelection("cards",[DEEP_REASONING_CARDS[0]]);state.session.revealed=true;render()');assert.ok(element('#app').innerHTML.includes(run('rich(DEEP_REASONING_CARDS[0].cardAnswer)')));run('rate(2);var chapterBackup=validate(JSON.parse(JSON.stringify(state)))');assert.ok(run('chapterBackup.cards[DEEP_REASONING_CARDS[0].id]'));assert.equal(run('Object.keys(chapterBackup.evidence).length'),0);});
test('New observed errors can reorder the daily chapter recommendations immediately',()=>{run('state=defaults();var beforeDynamic=Campaign.readingQueue(state,ALL_QUESTIONS,SYLLABUS,{count:1})[0].id;var testQ=DEEP_QUESTIONS.find(q=>q.reading==="CI-8");state.quiz[testQ.id]={...Engine.schedule(null,0,Date.now()-700000),...Coach.annotate(null,false,{now:Date.now()-700000,day:Campaign.dateKey(),confidence:"high"})};state.evidence[testQ.id]={at:Date.now()-700000,correct:false};var afterDynamic=Campaign.readingQueue(state,ALL_QUESTIONS,SYLLABUS,{count:1})[0].id');assert.equal(run('afterDynamic'),'CI-8');assert.notEqual(run('beforeDynamic'),run('afterDynamic'));});
